contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 rate, uint256 duration) public {
        require(amount > 0);
        require(rate <= 1e18);
        require(duration <= 365 days);
        // rate * duration < 365 days * 1e18 means the yearly-equivalent rate
        // is strictly below 100%, so the computed interest must stay below principal.
        require(rate * duration < 365 days * 1e18);

        uint256 interest = c.interestFor(amount, rate, duration);

        assert(interest < amount);
    }

    receive() external payable {}
}

