contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount, uint256 rate, uint256 duration) public {
        require(amount > 0 && amount <= 10**18);
        require(rate <= 10**18);
        require(duration <= 365 days);
        uint256 interest = c.interestFor(amount, rate, duration);
        // interest = (amount * ((rate*duration)/365days)) / 1e18
        // must not exceed the exact pro-rata interest
        assert(interest * 10**18 <= (amount * rate * duration) / 365 days);
    }
}
